void ALDTradeProbe::ServerTick()
{
    auto* M=GetWorld()->GetAuthGameMode<ALDGameMode>();auto* T=M->Trade.Get();auto* G=GetWorld()->GetGameState<ALDGameState>();const double E=FPlatformTime::Seconds()-PhaseAt,Now=GetWorld()->GetTimeSeconds();
    if(Phase==12){if(E>3){Finish();}return;}
    if(!Phase){for(FConstPlayerControllerIterator It=GetWorld()->GetPlayerControllerIterator();It;++It){if(auto* P=Cast<ALDPlayerController>(It->Get());P&&P->GetPawn()){if(P->ProbeRole==1){A=P;}if(P->ProbeRole==2){B=P;}}}if(A.IsValid()&&B.IsValid()){Check(G->LobbyCount==2&&G->bUIControlProfile,TEXT("Two independent clients use the ordinary V05 private lobby"));Enter(1);}return;}
    if(Phase==11&&bDisconnect){if(E>4){Check(!T->HasSession(A.Get())&&!M->StateFor(A.Get())->Inventory.Items.ContainsByPredicate([](const auto& I){return I.bReserved;}),TEXT("Actual remote disconnect releases the survivor's reservations without transfer"));Enter(12);}return;}
    if(!A.IsValid()||!B.IsValid()){Check(false,TEXT("Unexpected trade client disconnect"));Finish();return;}
    auto* OA=M->StateFor(A.Get());auto* OB=M->StateFor(B.Get());
    if(Phase==1&&G->bMatchStarted&&E>1)
    {
        int32 N=0;for(auto P:{A,B}){auto* O=M->StateFor(P.Get());P->GetPawn()->SetActorLocation(LDRegion::Site(GetWorld(),1)+FVector(N++?35:-35,0,92),false,nullptr,ETeleportType::TeleportPhysics);P->GetPawn()->SetActorRotation(FRotator::ZeroRotator);auto* C=M->Combat->StateFor(Cast<ALDCharacter>(P->GetPawn()));C->ProtectionUntil=0;O->ProtectedUntil=0;O->Gold=P==A?100:20;O->FabricationReceipt=FGuid::NewGuid();auto* Seal=GetWorld()->SpawnActor<ALDSeal>();check(M->Inventory->Adopt(P.Get(),Seal));while(O->Inventory.Items.Num()<(P==A?24:23)){auto* Book=GetWorld()->SpawnActor<ALDBook>();Book->Skill=ELDSkill::Patch;Book->State=0;check(M->Inventory->Adopt(P.Get(),Book));}FString Why;LDInventory::BindQuick(O->Inventory,O->Inventory.Items[0].Id,0,Why);LDInventory::BindQuick(O->Inventory,O->Inventory.Items[2].Id,1,Why);M->Inventory->Changed(P.Get());}ASeal=OA->SealId;BSeal=OB->SealId;AWard=OA->Inventory.Items[0].Id;ABook=OA->Inventory.Items[2].Id;BBook=OB->Inventory.Items[2].Id;Enter(2);
    }
    else if(Phase==2&&E>7){auto* S=T->Find(A.Get());Check(S&&S->Stage==ELDTradeStage::Draft,TEXT("Observed gesture, neutral invitation and receiver acceptance create one shared session"));if(!S){Finish();return;}Enter(3);}
    else if(Phase==3&&E>12){auto* S=T->Find(A.Get());Check(S&&S->Sides[0].Items.Num()==3&&S->Sides[1].Items.Num()==2&&S->Sides[0].Gold==95&&S->Sides[1].Gold==5,TEXT("Revisioned native edits reserve the actual book, charge and Seal offers with exposed gold"));Check(OA->Gold==100&&OB->Gold==20&&OA->Inventory.Items.Num()==24&&OB->Inventory.Items.Num()==23&&OA->Inventory.Quick[0]==AWard&&M->Inventory->Owned(A.Get(),AWard)->bReserved,TEXT("Reservations leave wallets, owners, capacity and locked quick references in place"));Enter(4);}
    else if(Phase==4&&E>4){auto* S=T->Find(A.Get());Check(S&&S->Stage==ELDTradeStage::Review&&!S->Sides[0].Confirmed&&!S->Sides[1].Confirmed&&OA->Gold==100,TEXT("Both Ready enter Review without committing or implying final confirmation"));Enter(5);}
    else if(Phase==5)
    {
        if(!Step){Thief=GetWorld()->SpawnActor<ALDResident>(A->GetPawn()->GetActorLocation()-FVector(70,0,0),FRotator::ZeroRotator);Thief->SetActorTickEnabled(false);auto Build=LDDevelopment::StartingBuild(1,M->CharacterCatalog());Build.Ranks[uint8(ELDSkill::Pickpocket)]=1;for(auto& Slot:Build.Slots){Slot=ELDSkill::None;}Build.Slots[0]=ELDSkill::Pickpocket;check(M->Combat->RegisterNPCBuild(Thief.Get(),Build));M->WorldChecks->EnsureTargets();M->WorldChecks->InjectTestRolls({20});FString Why;Check(M->Combat->RequestEquipped(Thief.Get(),Build.Revision,0,12345,FVector::ForwardVector,Why,A->GetPawn()),TEXT("Incoming theft starts the real retained one-second Pickpocket channel"));Step=1;}
        if(Thief.IsValid()){M->Combat->RefreshSkillHold(Thief.Get(),12345,++HoldSequence,false);}
        if(E>4){auto* S=T->Find(A.Get());Check(OA->Gold==88&&OB->Gold==20&&S&&S->Stage==ELDTradeStage::Draft&&!S->Sides[0].Ready&&!S->Sides[1].Ready&&S->Sides[0].Gold==95,TEXT("Real incoming theft transfers twelve from the unescrowed wallet and invalidates both approvals while keeping the invalid offer"));if(Thief.IsValid()){Thief->Destroy();}Enter(6);}
    }
    else if(Phase==6&&E>6){Check(T->Find(A.Get())&&T->Find(A.Get())->Stage==ELDTradeStage::Review,TEXT("Explicitly correcting the gold offer requires fresh Ready from both participants"));Enter(7);}
    else if(Phase==7&&E>5){Check(!T->HasSession(A.Get())&&OA->Gold==53&&OB->Gold==55&&OA->Inventory.Items.Num()==23&&OB->Inventory.Items.Num()==24,TEXT("Second independent confirmation atomically exchanges net-capacity bags and gold without a fee"));Check(OA->SealId==BSeal&&OB->SealId==ASeal&&M->Inventory->Owned(B.Get(),AWard)&&M->Inventory->Owned(B.Get(),ABook)&&M->Inventory->Owned(A.Get(),BBook)&&!OA->Inventory.Quick[0].IsValid()&&!OA->Inventory.Quick[1].IsValid()&&!OB->Inventory.Quick[1].IsValid(),TEXT("Transferred book, charge and swapped Seal keep physical identity and clear only transferred quick references"));Check(OA->FabricationReceipt.IsValid()&&OB->FabricationReceipt.IsValid()&&OA->Xp==0&&OB->Xp==0,TEXT("Exchange grants no XP and never resets the one-craft receipt"));Enter(8);}
    else if(Phase==8&&E>4){Check(OA->Gold==53&&OB->Gold==55,TEXT("Remote replay and late cancel retain the completed wallet outcome"));Draft();for(auto P:{A,B}){auto Items=M->StateFor(P.Get())->Inventory.Items;for(int32 N=0;N<6;++N){Cmd(P.Get(),LDTrade::Add,Items[N].Id);}}T->Push(*T->Find(A.Get()));Enter(9);}
    else if(Phase==9&&E>3){Check(T->Find(A.Get())->Sides[0].Items.Num()==6&&T->Find(A.Get())->Sides[1].Items.Num()==6,TEXT("Both full six-row offer trays exist as reserved authority state"));Enter(10);NextCase=0;}
    else if(Phase==10&&E>=NextCase){Cases(Step++);NextCase=E+.5;if(Step==10){T->CancelFor(A.Get());Draft();const auto BookA=*OA->Inventory.Items.FindByPredicate([](const auto& I){return I.Kind==ELDItemKind::Book;});const auto BookB=*OB->Inventory.Items.FindByPredicate([](const auto& I){return I.Kind==ELDItemKind::Book;});Cmd(A.Get(),LDTrade::Add,BookA.Id);Cmd(B.Get(),LDTrade::Add,BookB.Id);Cmd(A.Get(),LDTrade::Gold,FGuid(),1);Cmd(A.Get(),LDTrade::Ready);Cmd(B.Get(),LDTrade::Ready);Cmd(A.Get(),LDTrade::Confirm);T->Push(*T->Find(A.Get()));BeforeA=OA->Gold;BeforeB=OB->Gold;Enter(11);}}
    else if(Phase==11&&!bDisconnect)
    {
        if(!Step&&E>1.5){auto* S=T->Find(B.Get());Check(S&&S->Stage==ELDTradeStage::Review,TEXT("Final eligibility race begins from a real reserved Review with one confirmation"));T->Queue(B.Get(),OB->Match,OB->Life,1000000,LDTrade::Confirm,S->Id,S->Revision,S->Digest,FGuid(),0);if(bTerminal){G->MatchDeadline=float(Now-.001);}else{auto* Attacker=GetWorld()->SpawnActor<ALDResident>(A->GetPawn()->GetActorLocation()-FVector(70,0,0),FRotator::ZeroRotator);Attacker->SetActorTickEnabled(false);M->Combat->StateFor(Cast<ALDCharacter>(A->GetPawn()))->Hp=1;FString Why;Check(M->Combat->RequestBody(Attacker,0,FVector::ForwardVector,Why),TEXT("Final race uses an actual melee windup and due lethal impact"));T->Requests.Last().Due=M->Combat->StateFor(Attacker)->ImpactAt;}Step=1;}
        if(E>4){Check(!T->HasSession(A.Get())&&!T->HasSession(B.Get())&&OB->Gold==BeforeB&&(bTerminal?G->EndReason==2:!OA->bActive&&OA->Gold==BeforeA-LDDevelopment::DeathLoss(BeforeA)),bTerminal?TEXT("Actual No acquisition terminal state wins over queued confirmation without transfer"):TEXT("Due damage/death releases reservations before drops and gold loss; queued confirmation cannot transfer"));Enter(12);}
    }
}
void ALDTradeProbe::Capture(const FString& Name){if(bCapture&&Role==TEXT("A")){FScreenshotRequest::RequestScreenshot(FPaths::Combine(Dir,Name+TEXT(".png")),true,false);}}
void ALDTradeProbe::ClientTick()
{
    auto* PC=CastChecked<ALDPlayerController>(GetOwner());if(FPlatformTime::Seconds()-LastPing>.3){LastPing=FPlatformTime::Seconds();PC->ServerProbePing(LastPing);}if(PC->ProbePhase!=Phase){Phase=PC->ProbePhase;Step=0;PhaseAt=FPlatformTime::Seconds();}const double E=FPlatformTime::Seconds()-PhaseAt;const auto& O=PC->OwnerState;const auto& V=PC->TradeView;
    if(Phase==1){if(!Choice){PC->Controls->ResetBindings();if(FParse::Param(FCommandLine::Get(),TEXT("LDHUDLargeText"))){PC->Controls->TextScale=1.25f;}PC->RebuildV05Mappings();PC->ChooseLobbyClass(Role==TEXT("A")?1:2);Choice=true;}if(!Ready&&O.Build.ClassId==(Role==TEXT("A")?1:2)&&E>.5){PC->ToggleLobbyReady();Ready=true;}if(O.bLobbyHost&&O.bReady&&E>1){PC->StartLobby();}return;}
    if(Phase==2)
    {
        if(Role==TEXT("A")&&!Step&&E>1){const auto* R=PC->LocalView();if(R){for(const auto& Entity:R->LastView().Entities){if(Entity.Kind==ELDObservedKind::Body&&FVector::Dist2D(Entity.Position,PC->GetPawn()->GetActorLocation())>30&&FVector::Dist2D(Entity.Position,PC->GetPawn()->GetActorLocation())<100){PC->Inspect(Entity.Id);PC->OfferTrade();Step=1;break;}}}}
        if(Role==TEXT("B")&&V.Stage==ELDTradeStage::Invited&&!PC->TradePending()){PC->TradeCommand(LDTrade::Accept);Step=1;}
        if(Step==1&&V.Stage==ELDTradeStage::Draft){Check(PC->InventoryUI&&PC->InventoryUI->IsOpen()&&!PC->CanWorldCommand(),TEXT("Accepted exchange opens the same nonpausing own-bag shell and captures world input"));int32 Canonical=0;for(TActorIterator<ALDTradeDirector> It(GetWorld());It;++It){++Canonical;}for(TActorIterator<ALDItem> It(GetWorld());It;++It){++Canonical;}Check(!Canonical&&V.OtherItems.IsEmpty(),TEXT("Restricted trade client has no canonical trade/item actor or automatic partner bag payload"));Step=2;}
    }
    if(Phase==3&&E>.3&&!PC->TradePending())
    {
        TArray<uint8> Slots=Role==TEXT("A")?TArray<uint8>{0,1,2}:TArray<uint8>{1,2};for(auto Slot:Slots){const auto* Item=O.Inventory.Items.FindByPredicate([&](const auto& I){return I.Slot==Slot;});if(Item&&!V.OwnItems.ContainsByPredicate([&](const auto& I){return I.Handle==Item->Id;})){PC->InventoryUI->Select(Item->Id);PC->InventoryUI->Refresh();PC->InventoryUI->TradeSelected();return;}}
        const int64 Gold=Role==TEXT("A")?95:5;if(V.OwnGold!=Gold){PC->InventoryUI->TradeGold(Gold);return;}
        if(!Step){bool Private=true;for(const auto& I:V.OtherItems){Private&=!O.Inventory.Find(I.Handle);}Check(Private&&O.Gold==(Role==TEXT("A")?100:20),TEXT("Offer trays disclose only voluntarily offered definitions and temporary partner handles; wallets remain own-only"));Check(O.Inventory.Items.ContainsByPredicate([](const auto& I){return I.bReserved;})&&LDInventory::Valid(O.Inventory),TEXT("Native bag marks actual reservations while preserving valid locked references"));Step=1;}
    }
    if(Phase==4&&E>.5){if(!V.bOwnReady&&!PC->TradePending()){PC->InventoryUI->TradeReady();}if(V.Stage==ELDTradeStage::Review&&!Step&&!PC->TradePending()){Check(!V.bOwnConfirmed&&!V.bOtherConfirmed&&O.Gold==(Role==TEXT("A")?100:20),TEXT("Ready exposes Review and a separate final Confirm without moving any gold"));if(bCapture&&Role==TEXT("A")){auto* UI=PC->InventoryUI.Get();UI->Refresh();Check(UI->bTradeReview&&!UI->MainPanel->GetIsEnabled()&&UI->PanelFocusTargets().Num()==3,TEXT("Final review confines keyboard focus to Confirm, Back and Cancel above a disabled bag"));UI->ReviewBack->SetKeyboardFocus();FSlateApplication::Get().ProcessKeyDownEvent(FKeyEvent(EKeys::SpaceBar,FModifierKeysState(),0,false,0,0));FSlateApplication::Get().ProcessKeyUpEvent(FKeyEvent(EKeys::SpaceBar,FModifierKeysState(),0,false,0,0));Check(!UI->bTradeReview&&!V.bOwnConfirmed&&PC->ArmedSlot()==-1,TEXT("Native Space activates focused Back without confirming or arming a world skill"));UI->ConfirmTradeButton->SetKeyboardFocus();FSlateApplication::Get().ProcessKeyDownEvent(FKeyEvent(EKeys::Enter,FModifierKeysState(),0,false,0,0));FSlateApplication::Get().ProcessKeyUpEvent(FKeyEvent(EKeys::Enter,FModifierKeysState(),0,false,0,0));Check(UI->bTradeReview&&!V.bOwnConfirmed,TEXT("Native Enter opens the focused review action without submitting a confirmation"));FSlateApplication::Get().ProcessKeyDownEvent(FKeyEvent(EKeys::Escape,FModifierKeysState(),0,false,0,0));FSlateApplication::Get().ProcessKeyUpEvent(FKeyEvent(EKeys::Escape,FModifierKeysState(),0,false,0,0));Check(!UI->bTradeReview&&UI->IsOpen()&&V.Active(),TEXT("Native Escape dismisses review while keeping the unconfirmed exchange available for editing"));UI->ShowTradeReview();}Capture(TEXT("TradeReview"));Step=1;}}
    if(Phase==5&&E>2.5&&!Step){Check(V.Stage==ELDTradeStage::Draft&&!V.bOwnReady&&!V.bOtherReady&&(Role==TEXT("A")?O.Gold==88&&V.OwnGold==95&&!V.bOwnValid:O.Gold==20&&V.OtherGold==95&&!V.bOtherValid&&V.Message==TEXT("Other offer needs review")),TEXT("Incoming wallet change resets consent; only owner sees its balance and partner receives generic review state"));Step=1;}
    if(Phase==6&&E>.5&&!PC->TradePending()){if(Role==TEXT("A")&&V.OwnGold!=40){PC->InventoryUI->TradeGold(40);return;}if(V.bOwnValid&&V.bOtherValid&&!V.bOwnReady){PC->InventoryUI->TradeReady();}}
    if(Phase==7&&E>.5){if(!V.bOwnConfirmed&&!PC->TradePending()&&(Role==TEXT("A")||V.bOtherConfirmed)){PC->InventoryUI->TradeConfirm();}if(V.Stage==ELDTradeStage::Committed&&!Step){CompletedSession=V.Session;Check(O.Gold==(Role==TEXT("A")?53:55)&&O.Inventory.Items.Num()==(Role==TEXT("A")?23:24)&&PC->InventoryUI->TradeText().Contains(TEXT("COMPLETED")),TEXT("Native final receipt shows the actual committed items/gold and projected bag result"));Capture(TEXT("TradeCompleted"));Step=1;}}
    if(Phase==8){if(!Step&&E>.5){PC->InventoryUI->Close();PC->ServerTradeCommand(O.Match,O.Life,++PC->NextRequest,LDTrade::Cancel,CompletedSession,V.Revision,V.Digest,FGuid(),0);Step=1;}if(Step==1&&E>2){Check(!PC->InventoryUI->IsOpen()&&O.Gold==(Role==TEXT("A")?53:55),TEXT("Late cancel after closing a completed receipt cannot reopen it or report a rollback"));Step=2;}}
    if(Phase==9&&E>1&&!Step){Check(V.OwnItems.Num()==6&&V.OtherItems.Num()==6&&PC->InventoryUI->IsOpen(),TEXT("Both native trays contain six real reserved offers without the partner's remaining bag"));if(bCapture&&Role==TEXT("A")){auto* UI=PC->InventoryUI.Get();UI->GoldInput->SetText(FText::GetEmpty());UI->GoldInput->SetKeyboardFocus();FSlateApplication::Get().ProcessKeyCharEvent(FCharacterEvent(TEXT('1'),FModifierKeysState(),0,false));FSlateApplication::Get().ProcessKeyCharEvent(FCharacterEvent(TEXT('2'),FModifierKeysState(),0,false));Check(UI->GoldInput->GetText().ToString()==TEXT("12")&&PC->ArmedSlot()==-1&&!PC->ArmedItem().IsValid(),TEXT("Native amount typing retains digits in the field without quick-item or skill activation"));UI->GoldInput->SetText(FText::FromString(FString::Printf(TEXT("%lld"),V.OwnGold)));}Capture(TEXT("TradeSixItems"));Step=1;}
    if(Phase==11){if(bDisconnect&&Role==TEXT("B")&&E>.5){Check(V.Active(),TEXT("Remote client exits with an active reserved exchange for disconnect cleanup"));Finish();return;}if(E>3&&!Step){Check(!V.Active()&&(!PC->InventoryUI||!PC->InventoryUI->IsOpen()),TEXT("Death, terminal state or remote disconnect closes the actual peer exchange shell"));Step=1;}}
    if(Phase==12&&E>.8){Check(true,TEXT("Independent trade client completed all assigned phases"));Finish();}
}
